class Resource extends Base {
 mount(){this.items??=[{label:'Discover',body:'Start at the edges. Follow the things that make you curious.'},{label:'Collect',body:'Keep the fragments that feel like the beginning of something.'},{label:'Compose',body:'Put two unlikely things together and see what happens.'},{label:'Refine',body:'Give every detail a reason to stay.'},{label:'Release',body:'Send the work into the world. Leave the door open.'}];this.selected=0;this.render(`<section class="scene"><div class="orbit" role="group" aria-label="Creative process"><div class="ring ring-two"></div><div class="ring"></div><div class="center"><span>THE PROCESS</span><b>∞</b><small>no straight lines</small></div>${this.items.map((item,i)=>`<button data-index="${i}" aria-pressed="${i===0}" tabindex="${i===0?0:-1}"><span>0${i+1}</span><strong>${escape(item.label)}</strong></button>`).join('')}</div><div class="copy" aria-live="polite"><span class="label">01 / CREATIVE PROCESS</span><h2>Discover</h2><p>${escape(this.items[0].body)}</p></div></section>`,`.scene{background:radial-gradient(ellipse at 35% 40%,#41524022,transparent 65%),var(--bg);border:1px solid var(--line);border-radius:var(--radius);padding:30px 20px;min-height:510px;display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:26px}.orbit{width:340px;height:340px;position:relative;max-width:100%;flex-shrink:0}.ring{position:absolute;inset:38px;border:1px solid #c6e6b028;border-radius:50%}.ring-two{inset:65px;border-style:dashed;opacity:.5}.center{position:absolute;inset:105px;border:1px solid var(--line);border-radius:50%;display:flex;flex-direction:column;align-items:center;justify-content:center;background:var(--panel)}.center span{font-size:6px;letter-spacing:1.2px;color:var(--muted)}.center b{font:400 55px Georgia;color:var(--accent);line-height:1.15}.center small{font-size:7px;color:var(--muted)}.orbit button{position:absolute;left:50%;top:50%;width:70px;height:70px;margin:-35px;border:1px solid var(--line);border-radius:50%;background:var(--panel);display:flex;flex-direction:column;gap:4px;align-items:center;justify-content:center}.orbit button span{font-size:8px;color:var(--muted)}.orbit button strong{font-size:9px;font-weight:500}.orbit button[aria-pressed=true]{border-color:var(--accent);box-shadow:0 0 30px #b6d19f15;color:var(--accent)}.copy{max-width:245px}.copy h2{font:400 39px Georgia;margin:16px 0}.copy p{font-size:13px;line-height:1.9;color:var(--muted)}@media(max-width:480px){.scene{padding:18px 10px;gap:4px}.orbit{width:310px;height:310px}.center{inset:95px}.copy{text-align:center;max-width:260px;padding:0 0 20px}.copy h2{font-size:30px;margin:10px 0}.copy p{font-size:12px}}`);this.listen(this.$('.orbit'),'click',e=>{const button=e.target.closest('button');if(button)this.select(Number(button.dataset.index));});this.listen(this.$('.orbit'),'keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(e.key))return;e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?this.items.length-1:(this.selected+(['ArrowLeft','ArrowUp'].includes(e.key)?-1:1)+this.items.length)%this.items.length;this.select(next);this.$$('button')[next].focus();});this.animate((dt,time)=>this.position(time));}
 position(time=0){const box=this.$('.orbit');const radius=Math.min(this.number('radius',130,85,160),box.clientWidth*.39);this.$$('button').forEach((button,i)=>{const a=i*Math.PI*2/this.items.length-Math.PI/2+(this.reduced?0:Math.sin(time*.25)*.06*this.number('speed',1,.2,2));button.style.transform=`translate(${Math.cos(a)*radius}px,${Math.sin(a)*radius}px)`;});}
 resized(){this.position(this.time);}
 select(index){if(!this.items[index])return;this.selected=index;this.$$('button').forEach((b,i)=>{b.tabIndex=i===index?0:-1;b.setAttribute('aria-pressed',String(i===index));});this.$('.copy h2').textContent=this.items[index].label;this.$('.copy p').textContent=this.items[index].body;this.$('.copy .label').textContent=`0${index+1} / CREATIVE PROCESS`;this.emit('orbit-change',{index,label:this.items[index].label});}
}
